import pandas as pd
import numpy as np
import itertools

def task_func(data_list=[('a', 1, 2.1), ('b', 2, 3.2), ('c', 3, 4.3), ('d', 4, 5.4), ('e', 5, 6.5)]):
    if not data_list:
        return pd.DataFrame()

    # Determine the maximum number of positions across all tuples
    max_len = max(len(t) for t in data_list) if data_list else 0

    if max_len == 0:
        return pd.DataFrame()

    means = []
    for i in range(max_len):
        values = []
        for t in data_list:
            if i < len(t):
                val = t[i]
                if isinstance(val, (int, float)):
                    values.append(val)
        if values:
            means.append(np.mean(values))
        else:
            means.append(np.nan)

    index = [f'Position {i}' for i in range(max_len)]
    df = pd.DataFrame({'Mean Value': means}, index=index)
    return df

import pandas as pd
import csv
from difflib import ndiff

def task_func(file_path1, file_path2, delimiter=',', quotechar='"'):
    try:
        with open(file_path1, 'r', newline='') as f1:
            lines1 = f1.read().splitlines()
        with open(file_path2, 'r', newline='') as f2:
            lines2 = f2.read().splitlines()
    except FileNotFoundError:
        raise FileNotFoundError(f"File not found: {file_path1} or {file_path2}")
    except Exception as e:
        raise Exception(f"IO error: {e}")

    if not lines1:
        raise ValueError(f"File {file_path1} is empty")
    if not lines2:
        raise ValueError(f"File {file_path2} is empty")

    # Use ndiff to compare lines
    diff = list(ndiff(lines1, lines2))

    results = []
    line_number = 1
    for d in diff:
        if d.startswith(' '):
            results.append({'Line Number': line_number, 'Status': ' ', 'Content': d[1:]})
            line_number += 1
        elif d.startswith('-'):
            results.append({'Line Number': line_number, 'Status': '-', 'Content': d[1:]})
            line_number += 1
        elif d.startswith('+'):
            results.append({'Line Number': line_number, 'Status': '+', 'Content': d[1:]})
            line_number += 1

    df = pd.DataFrame(results)
    return df

import pandas as pd
from datetime import datetime
import random

def task_func(
    epoch_milliseconds,
    random_seed=0,
    products=["Product1", "Product2", "Product3", "Product4", "Product5"],
):
    # Validate input
    if not isinstance(epoch_milliseconds, (int, float)):
        raise ValueError("epoch_milliseconds must be a number")
    if epoch_milliseconds < 0:
        raise ValueError("epoch_milliseconds must be non-negative")
    if not isinstance(products, list) or len(products) != 5:
        raise ValueError("products must be a list of exactly 5 items")
    if not all(isinstance(p, str) for p in products):
        raise ValueError("all products must be strings")
    if not isinstance(random_seed, (int, float)):
        raise ValueError("random_seed must be a number")

    random.seed(random_seed)

    # Convert epoch milliseconds to datetime
    start_date = datetime.fromtimestamp(epoch_milliseconds / 1000)
    current_date = datetime.now()

    # Ensure start_date is not after current_date
    if start_date > current_date:
        raise ValueError("epoch_milliseconds must represent a time in the past or present")

    # Generate dates from start_date to current_date (inclusive of days)
    start_day = start_date.date()
    end_day = current_date.date()

    sales_data = []
    for day in range((end_day - start_day).days + 1):
        date = start_day + pd.Timestamp(day).date()
        for product in products:
            sales = random.randint(10, 50)
            sales_data.append({"Product": product, "Date": date, "Sales": sales})

    return pd.DataFrame(sales_data)
